#define CHECK(expr) do{++checks;if(!(expr)){fprintf(stderr,"FAIL %d: %s (tick%d pos%d,%d kind%d)\n",__LINE__,#expr,g.tick,g.units[0].x,g.units[0].y,g.cast_orders[0].kind);exit(1);}}while(0)
static void setup(int hero){int i;dota_init(&g,hero,73);g.tick=2000;for(i=1;i<DOTA_MAX_UNITS;i++)g.units[i].active=0;for(i=0;i<4;i++)g.units[0].learned[i]=1;g.units[0].mana=g.units[0].max_mana=10000;g.units[0].attack_wait=100000;dota_rules_set_position(&g,0,sx,sy);dota_nav_set_all_structures(0,0,0);dota_nav_set_item_trees(g.item_world.tree,DOTA_ITEM_TREES);dota_nav_set_static_trees(&g);dota_sight_invalidate();}
static void target(int x,int y){g.units[1]=g.units[0];g.units[1].active=1;g.units[1].x=x;g.units[1].y=y;g.units[1].generation=7;g.units[1].team=1;g.units[1].hero_id=DOTA_HERO_AXE;g.units[1].speed=0;g.units[1].hp=g.units[1].max_hp=5000;dota_sight_invalidate();}
static void step(void){int ox=g.units[0].x,oy=g.units[0].y;++g.tick;dota_cast_order_tick(&g,0);if(g.units[0].x!=ox||g.units[0].y!=oy)CHECK(dota_nav_segment(ox,oy,g.units[0].x,g.units[0].y));CHECK(g.navigation_searches<=4&&g.navigation_nodes<=4096);if(trace)fprintf(trace,"%d,%d,%d,%d,%d,%d,%u\n",g.tick,g.units[0].x,g.units[0].y,g.cast_orders[0].kind,g.units[0].mana,g.units[0].cooldown[1],dota_nav_stats()->path_queries);}
static int finish(int limit){int n;for(n=0;n<limit&&dota_cast_order_active(&g,0);n++)step();return n;}
static void find_corridor(void){int x,y;setup(DOTA_HERO_AXE);for(y=1208;y<3000;y+=64)for(x=1208;x<2800;x+=64)if(dota_nav_walkable(x,y)&&dota_nav_segment(x,y,x+320,y)){sx=x;sy=y;tx=x+320;ty=y;return;}CHECK(0);}
static void unit_walk_and_cost(void){int n,cost,range;setup(DOTA_HERO_AXE);target(tx,ty);CHECK(dota_unit_visible(&g,0,1));CHECK(!dota_cast_on_unit(&g,1,1,7));CHECK(g.units[0].mana==10000&&!g.units[0].cooldown[1]);cost=dota_skill_mana_cost(&g,0,1);range=dota_skill_cast_range_source(&g,0,1);CHECK(dota_order_cast_on_unit(&g,1,1,7)==2);CHECK(g.units[0].mana==10000&&!g.units[0].cooldown[1]);for(n=0;n<200&&dota_cast_order_active(&g,0);n++){step();if(dota_cast_order_active(&g,0))CHECK(g.units[0].mana==10000&&!g.units[0].cooldown[1]&&!g.units[1].dot_ticks);}CHECK(n>1&&n<200);CHECK(g.units[0].mana==10000-cost&&g.units[0].cooldown[1]>0&&g.units[1].dot_source==0&&g.units[1].dot_ticks>0);CHECK((long long)(g.units[0].x-tx)*(g.units[0].x-tx)*16<=range*range);cases++;}
static void moving_locked_target(void){int n;setup(DOTA_HERO_AXE);target(tx,ty);g.units[2]=g.units[1];g.units[2].generation=8;g.units[2].x=tx-40;CHECK(dota_order_cast_on_unit(&g,1,1,7)==2);for(n=0;n<200&&dota_cast_order_active(&g,0);n++){if(n<15&&n%3==0){g.units[1].x+=2;dota_sight_invalidate();}step();}CHECK(n<200&&g.units[1].dot_ticks>0&&!g.units[2].dot_ticks);CHECK(g.units[0].mana<10000);cases++;}
static void cancellation(void){int mode;DotaInput input;for(mode=0;mode<10;mode++){setup(DOTA_HERO_AXE);target(tx,ty);CHECK(dota_order_cast_on_unit(&g,1,1,7)==2);memset(&input,0,sizeof(input));switch(mode){case 0:dota_move_to(&g,sx,sy);break;case 1:dota_attack_target(&g,1);break;case 2:input.actions=DOTA_INPUT_STOP;dota_tick(&g,&input);break;case 3:input.move_x=1;dota_tick(&g,&input);break;case 4:g.units[1].hp=0;step();break;case 5:g.units[1].generation++;step();break;case 6:g.units[0].generation++;step();break;case 7:g.units[1].x=4000;g.units[1].y=100;dota_sight_invalidate();step();break;case 8:g.units[0].hp=0;step();break;case 9:CHECK(!dota_order_cast(&g,2,tx,ty));break;}CHECK(!dota_cast_order_active(&g,0)&&!g.units[0].cooldown[1]&&!g.units[1].dot_ticks);cases++;}}
static void waits_and_limits(void){int n,x,y;setup(DOTA_HERO_AXE);target(tx,ty);g.units[0].stun_ticks=20;CHECK(dota_order_cast_on_unit(&g,1,1,7)==2);for(n=0;n<20;n++){step();CHECK(g.units[0].x==sx&&g.units[0].y==sy&&g.units[0].mana==10000);}g.units[0].stun_ticks=0;CHECK(finish(200)<200&&g.units[1].dot_ticks);cases++;
 setup(DOTA_HERO_AXE);target(tx,ty);g.units[0].speed=0;CHECK(dota_order_cast_on_unit(&g,1,1,7)==2);x=g.units[0].x;y=g.units[0].y;CHECK(finish(150)<=101);CHECK(!g.units[0].cooldown[1]&&g.units[0].mana==10000&&g.units[0].x==x&&g.units[0].y==y);cases++;
 setup(DOTA_HERO_AXE);target(tx,ty);g.units[0].mana=0;CHECK(!dota_order_cast_on_unit(&g,1,1,7));CHECK(!dota_cast_order_active(&g,0));g.units[0].mana=10000;g.units[0].cooldown[1]=100;CHECK(!dota_order_cast_on_unit(&g,1,1,7));CHECK(!dota_cast_order_active(&g,0));cases++;
 setup(DOTA_HERO_AXE);target(tx,ty);CHECK(dota_order_cast_on_unit(&g,1,1,7)==2);g.units[0].mana=0;step();CHECK(!dota_cast_order_active(&g,0)&&!g.units[1].dot_ticks);cases++;}
static void real_navigation(void){int x,y,n,found=0;unsigned paths=0;for(y=1400;y<2600&&!found;y+=64)for(x=1400;x<2600&&!found;x+=64){setup(DOTA_HERO_LINA);if(!dota_nav_walkable(x,y)||!dota_nav_walkable(x+350,y+80)||dota_nav_segment(x,y,x+190,y+44))continue;dota_rules_set_position(&g,0,x,y);dota_nav_reset_stats();if(dota_order_cast(&g,1,x+350,y+80)!=2)continue;n=finish(350);if(n<350&&g.units[0].cooldown[1]&&dota_nav_stats()->path_queries){found=1;paths=dota_nav_stats()->path_queries;printf("NAV start%d,%d target%d,%d ticks%d paths%u\n",x,y,x+350,y+80,n,paths);}}CHECK(found&&paths<40);cases++;}
static void tree_items(void){int i,n,stamp;for(i=0;i<DOTA_STATIC_TREE_COUNT;i++){xy[i*2]=4000;xy[i*2+1]=4000;}xy[0]=(uint16_t)tx;xy[1]=(uint16_t)ty;CHECK(dota_trees_attach(xy,DOTA_STATIC_TREE_COUNT));setup(DOTA_HERO_AXE);CHECK(dota_items_receive(&g,0,DOTA_ITEM_TANGO,201));printf("TREE visible%d query%d center%d,%d item%d\n",dota_sight_team_position_visible(&g,0,tx,ty),dota_items_cast_query(&g,0,0,tx,ty,-1,&stamp),tx,ty,dota_items_cast_item(&g,0,0));CHECK(dota_order_item_tree(&g,0,0)==2);CHECK(g.items.charges[0][0]==3&&!dota_trees_is_cut(&g,0));for(n=0;n<200&&dota_cast_order_active(&g,0);n++){step();if(dota_cast_order_active(&g,0))CHECK(g.items.charges[0][0]==3&&!dota_trees_is_cut(&g,0));}CHECK(n<200&&dota_trees_is_cut(&g,0)&&g.items.charges[0][0]==2);cases++;
 setup(DOTA_HERO_AXE);CHECK(dota_items_receive(&g,0,DOTA_ITEM_TANGO,201));CHECK(dota_order_item_tree(&g,0,0)==2);CHECK(dota_trees_cut(&g,0));step();CHECK(!dota_cast_order_active(&g,0)&&g.items.charges[0][0]==3);cases++;dota_trees_detach();
 setup(DOTA_HERO_AXE);CHECK(dota_items_receive(&g,0,DOTA_ITEM_TANGO,201));g.item_world.tree[0].x=tx;g.item_world.tree[0].y=ty;g.item_world.tree[0].until=g.tick+1000;g.item_world.tree[0].source_item=DOTA_ITEM_BRANCHES;dota_sight_invalidate();CHECK(dota_order_item_at(&g,0,tx,ty,-1,0)==2);stamp=g.cast_orders[0].target_generation;CHECK(g.cast_orders[0].target==DOTA_STATIC_TREE_COUNT&&stamp==g.tick+1000);g.item_world.tree[0].until++;step();CHECK(!dota_cast_order_active(&g,0)&&g.items.charges[0][0]==3&&!g.item_world.tree[0].removed);cases++;
 setup(DOTA_HERO_AXE);CHECK(dota_items_receive(&g,0,DOTA_ITEM_TANGO,201));g.item_world.tree[0].x=tx;g.item_world.tree[0].y=ty;g.item_world.tree[0].until=g.tick+1000;g.item_world.tree[0].source_item=DOTA_ITEM_BRANCHES;dota_sight_invalidate();CHECK(dota_order_item_at(&g,0,tx,ty,-1,0)==2);CHECK(finish(200)<200&&g.item_world.tree[0].removed&&g.items.charges[0][0]==2);cases++;}
static void targeted_items_and_identity(void){int n,oldmana,oldhp;setup(DOTA_HERO_AXE);target(tx,ty);CHECK(dota_items_receive(&g,0,DOTA_ITEM_DAGON,201));(void)dota_move_speed_source(&g,0);oldmana=g.units[0].mana;CHECK(dota_order_item_at(&g,0,tx,ty,1,7)==2);oldhp=g.units[1].hp;for(n=0;n<200&&dota_cast_order_active(&g,0);n++){step();if(dota_cast_order_active(&g,0))CHECK(g.units[0].mana==oldmana&&!g.items.cooldown[0][0]&&g.units[1].hp==oldhp);}CHECK(n<200&&g.items.cooldown[0][0]>0&&g.units[1].hp<oldhp&&g.units[0].mana<oldmana);cases++;
 setup(DOTA_HERO_AXE);target(tx,ty);CHECK(dota_items_receive(&g,0,DOTA_ITEM_DAGON,201));CHECK(dota_order_item_at(&g,0,tx,ty,1,7)==2);oldhp=g.units[1].hp;g.units[0].inventory[0]=DOTA_ITEM_FORCE_STAFF;step();CHECK(!dota_cast_order_active(&g,0)&&g.units[1].hp==oldhp);cases++;}
static void actual_tick_and_point(void){int n;DotaInput input={0};setup(DOTA_HERO_LINA);CHECK(dota_order_cast(&g,1,tx,ty)==2);for(n=0;n<200&&dota_cast_order_active(&g,0);n++)dota_tick(&g,&input);CHECK(n>1&&n<200&&g.units[0].cooldown[1]>0);cases++;setup(DOTA_HERO_AXE);CHECK(dota_order_cast(&g,0,4000,4000)==1&&!dota_cast_order_active(&g,0)&&g.units[0].x==sx&&g.units[0].y==sy);cases++;}
static void windup_and_range_boundary(void){int n,mana,range;setup(DOTA_HERO_SVEN);target(tx,ty);CHECK(dota_order_cast_on_unit(&g,0,1,7)==2);mana=g.units[0].mana;CHECK(finish(200)<200);CHECK(g.roster.hero[0].cast_at>g.tick&&g.roster.hero[0].cast_target==1&&g.roster.hero[0].cast_generation==7);CHECK(g.units[0].mana==mana&&!g.units[0].cooldown[0]);for(n=0;n<30&&!g.units[0].cooldown[0];n++){g.tick++;dota_roster_tick(&g);}CHECK(n<30&&g.units[0].mana<mana&&g.units[0].cooldown[0]>0);cases++;
 setup(DOTA_HERO_AXE);range=dota_skill_cast_range_source(&g,0,1);target(sx+range/4,sy);CHECK(dota_order_cast_on_unit(&g,1,1,7)==1&&g.units[0].x==sx&&g.units[0].y==sy);cases++;
 setup(DOTA_HERO_AXE);target(sx+range/4+1,sy);CHECK(dota_order_cast_on_unit(&g,1,1,7)==2&&!g.units[0].cooldown[1]);CHECK(finish(20)<20&&g.units[0].cooldown[1]>0);cases++;
 setup(DOTA_HERO_AXE);target(tx,ty);CHECK(dota_order_cast_on_unit(&g,1,1,7)==2);dota_set_paused(&g,1);mana=g.tick;{DotaInput in={0};dota_tick(&g,&in);}CHECK(g.tick==mana&&dota_cast_order_active(&g,0)&&g.units[0].x==sx);dota_set_paused(&g,0);dota_restart(&g);CHECK(!dota_cast_order_active(&g,0));cases++;}
/* Expected normal inputs from the installed Valve AbilityBehavior records.
 * Cover unlearned skills too: learning/range upgrades must not change input. */
static void target_kind_matrix(void){
 static const unsigned char expected[10][4]={{0,2,0,2},{1,1,0,2},{0,1,0,2},{1,2,0,0},{0,0,2,0},{0,0,0,2},{1,0,0,2},{1,0,0,2},{2,0,0,0},{2,0,0,0}};
 int h,s,learned;for(h=0;h<10;h++){setup(h);for(learned=0;learned<2;learned++)for(s=0;s<4;s++){g.units[0].learned[s]=(unsigned char)learned;CHECK(dota_cast_order_skill_kind(&g,0,s)==expected[h][s]);CHECK(dota_input_skill_target_kind(&g,s)==expected[h][s]);}cases++;}
 setup(DOTA_HERO_TIDEHUNTER);CHECK(dota_items_receive(&g,0,DOTA_ITEM_ULTIMATE_SCEPTER,201));CHECK(dota_input_skill_target_kind(&g,0)==DOTA_INPUT_TARGET_POINT);cases++;
 setup(DOTA_HERO_PUDGE);CHECK(dota_items_receive(&g,0,DOTA_ITEM_AGHANIMS_SHARD,201));CHECK(dota_input_skill_target_kind(&g,3)==DOTA_INPUT_TARGET_ANY);cases++;
 setup(DOTA_HERO_SLARK);CHECK(dota_items_receive(&g,0,DOTA_ITEM_ULTIMATE_SCEPTER,201));CHECK(dota_input_skill_target_kind(&g,1)==DOTA_INPUT_TARGET_NONE);CHECK(dota_items_receive(&g,0,DOTA_ITEM_AGHANIMS_SHARD,201));CHECK(dota_input_skill_target_kind(&g,4)==DOTA_INPUT_TARGET_POINT);cases++;
 setup(DOTA_HERO_CRYSTAL_MAIDEN);CHECK(dota_items_receive(&g,0,DOTA_ITEM_AGHANIMS_SHARD,201));CHECK(dota_input_skill_target_kind(&g,4)==DOTA_INPUT_TARGET_POINT);cases++;
}
static void pounce_facing(void){
 static const signed char dx[8]={1,1,0,-1,-1,-1,0,1},dy[8]={0,1,1,1,0,-1,-1,-1};int i,cost,mana,ox,oy;DotaInput in={0};
 for(i=0;i<8;i++){setup(DOTA_HERO_SLARK);target(sx-dx[i]*50,sy-dy[i]*50);dota_hero_face(&g,0,sx+dx[i]*100,sy+dy[i]*100);cost=dota_skill_mana_cost(&g,0,1);mana=g.units[0].mana;
  CHECK(dota_order_cast(&g,1,sx-dx[i]*1000,sy-dy[i]*1000)==DOTA_ORDER_EXECUTED);CHECK(!dota_cast_order_active(&g,0));CHECK(g.extra.hero[0].leap_at==g.tick+1);CHECK(g.units[0].mana==mana-cost&&g.units[0].cooldown[1]>0);
  ox=g.extra.hero[0].leap_to_x-sx;oy=g.extra.hero[0].leap_to_y-sy;CHECK(ox*dx[i]>=0&&oy*dy[i]>=0);CHECK((!dx[i]&&!ox)||(dx[i]&&ox));CHECK((!dy[i]&&!oy)||(dy[i]&&oy));CHECK(g.units[0].x==sx&&g.units[0].y==sy);cases++;
 }
 setup(DOTA_HERO_SLARK);in.move_x=1;dota_tick(&g,&in);CHECK(g.units[0].x>sx&&g.units[0].y==sy);in.move_x=0;in.actions=DOTA_INPUT_STOP;dota_tick(&g,&in);ox=g.units[0].x;CHECK(dota_cast(&g,1,0,sy));CHECK(g.extra.hero[0].leap_to_x>ox&&g.extra.hero[0].leap_to_y==sy);cases++;
 setup(DOTA_HERO_SLARK);target(sx,sy-16);g.units[0].attack_wait=0;dota_rules_attack_once(&g,0,1);CHECK(g.attack_event_count>0);CHECK(dota_cast(&g,1,4000,4000));CHECK(g.extra.hero[0].leap_to_x==sx&&g.extra.hero[0].leap_to_y<sy);cases++;
 setup(DOTA_HERO_SLARK);g.extra.hero[0].leash_until=g.tick+20;mana=g.units[0].mana;CHECK(!dota_order_cast(&g,1,tx,ty));CHECK(!g.extra.hero[0].leap_at&&g.units[0].mana==mana&&!g.units[0].cooldown[1]);cases++;
 setup(DOTA_HERO_SLARK);CHECK(dota_items_receive(&g,0,DOTA_ITEM_ULTIMATE_SCEPTER,201));dota_hero_face(&g,0,sx+100,sy);CHECK(dota_order_cast(&g,1,0,0)==1&&g.extra.hero[0].pounce_charges==1);CHECK(g.extra.hero[0].leap_to_x==sx+225);cases++;
}
static void optional_ally_item(void){int charges;setup(DOTA_HERO_AXE);target(tx,ty);g.units[1].team=0;g.units[1].mana=0;CHECK(dota_items_receive(&g,0,DOTA_ITEM_ENCHANTED_MANGO,201));charges=dota_items_charges(&g,0,0);CHECK(dota_order_item_at(&g,0,tx,ty,1,7)==DOTA_ORDER_QUEUED);CHECK(dota_items_charges(&g,0,0)==charges&&g.units[1].mana==0);CHECK(finish(200)<200&&g.units[1].mana>0);CHECK(dota_items_charges(&g,0,0)==charges-1);cases++;}
int main(int argc,char**argv){void *work;CHECK(argc==3);CHECK(baked_io_open(argv[1])&&item_assets_open());work=malloc(dota_sight_workspace_bytes());CHECK(work&&dota_sight_attach(heights,tree_mask,work,dota_sight_workspace_bytes()));trace=fopen(argv[2],"w");CHECK(trace);fprintf(trace,"tick,x,y,order,mana,skill_w_cd,path_queries\n");find_corridor();unit_walk_and_cost();moving_locked_target();cancellation();waits_and_limits();real_navigation();tree_items();targeted_items_and_identity();actual_tick_and_point();windup_and_range_boundary();target_kind_matrix();pounce_facing();optional_ally_item();fclose(trace);dota_sight_detach();free(work);dota_trees_detach();item_assets_close();baked_io_close();printf("RESULT {\"passed\":true,\"checks\":%d,\"cases\":%d,\"game_bytes\":%u,\"order_bytes_per_hero\":%u,\"actual_navigation\":true,\"physical_h1_tested\":false}\n",checks,cases,(unsigned)sizeof(g),(unsigned)sizeof(DotaCastOrder));return 0;}
